/**
 * TRIPLE-NEGATIVE BREAST CANCER: TREATMENTS AND TRIALS. Facts checked 2026-09-24 against the primary papers (Europe PMC
 * abstracts), the ClinicalTrials.gov v2 API, the ISRCTN registry, openFDA labels, the EMA product pages and the NICE
 * guidance pages, each quoted with its URL.
 *
 * The cancer record itself is `tnbc` (../cancers.ts). TN below is the id every record here links to. The `patch` is
 * merged onto that record by mergeSpikeInto (./index.ts); `tnbcStandardOfCare` is exported in full so the cancer record
 * and the UK pass can draw on the rows the patch filters out (the core record already carries the stage I, stage II to
 * III and metastatic first-line rows).
 *
 * Existing TNBC records are extended, never duplicated. KEYNOTE-522, KEYNOTE-355, IMpassion130, ASCENT, ASCENT-03/04,
 * TROPION-Breast02/05, DESTINY-Breast04, OlympiA (../trials.ts), OlympiAD, EMBRACA, IMpassion031 (../breast-subtypes.ts),
 * IMpassion131 (../failures.ts), BrighTNess and GeparSixto (../trials-subtypes-wave.ts), ASCENT-05 and TROPION-Breast03
 * (../pipeline-trials.ts), CAPItello-290 (`nct03997123`), TROPION-Breast04 (`nct06112379`) and BEGONIA (`nct03742102`,
 * ../pipeline-trials-wave6.ts) receive supplements (UK sites, subgroup readings, later papers) through the spike
 * `supplements` field, which appends arrays and fills empty scalars. Their structured outcomes live in
 * ../trial-outcomes.ts and are not repeated here.
 */
const asOf = "2026-09-24";
export const TN = "tnbc";
const ct = (nct: string) => ({ label: `ClinicalTrials.gov ${nct}`, url: `https://clinicaltrials.gov/study/${nct}` });
const doi = (label: string, id: string) => ({ label, url: `https://doi.org/${id}` });
const nice = (ta: string, label: string) => ({ label, url: `https://www.nice.org.uk/guidance/${ta}` });

const t = (x: Omit<TrialInput, "kind" | "asOf">): TrialInput => ({ kind: "trial", asOf, ...x });
const d = (x: Omit<DrugInput, "kind" | "asOf">): DrugInput => ({ kind: "drug", asOf, ...x });
const term = (x: Omit<TermInput, "kind" | "asOf">): TermInput => ({ kind: "term", asOf, ...x });

